* born.F
* form factors for {Men(offshell W)} -> {l, nu_l} = i1 -> i2 + i3
* generated by FormCalc 14 Sep 2012 15:50

	subroutine P0decayWll(amp, i1, i2, i3)
	use basic_funcs_FC6
	implicit none
	double complex amp, Fx1
	integer i1, i2, i3, i, j

	double precision qext(4,3), kext

#include "vars.h"

	Fx1 = Hel(i2)*SxS(DottedSpinor(i3,1,7),VxS(e(i1),Spinor(i2,-1,7)))
	amp = EL*Fx1/(SW*Sqrt(2.D0))

#ifdef DEBUG
c	DEB 'decayWll: vec =', vec(1,1,1,i2), Hel(i2)
c	DEB 'decayWll: amp =', amp, Fx1

        print*,'from PrintPSP decayWll:'

        do i=i1, i1
        kext=momspec(SPEC_K,i)
        qext(1,1)=momspec(SPEC_E,i)
        qext(2,1)=momspec(SPEC_EX,i)*kext
        qext(3,1)=momspec(SPEC_EY,i)*kext
        qext(4,1)=momspec(SPEC_EZ,i)*kext
	enddo
	
        do i=i2, i3
        kext=momspec(SPEC_K,i)
        qext(1,i-i2+2)=momspec(SPEC_E,i)
        qext(2,i-i2+2)=momspec(SPEC_EX,i)*kext
        qext(3,i-i2+2)=momspec(SPEC_EY,i)*kext
        qext(4,i-i2+2)=momspec(SPEC_EZ,i)*kext
	enddo	

        do i=1,3
        print*,'[E, px, py, pz] of particle',i
        print*,qext(1,i),qext(2,i),qext(3,i),qext(4,i)
        print*,'mass2=',qext(1,i)**2-qext(2,i)**2-qext(3,i)**2-qext(4,i)**2
	enddo

        do i=1,4
	kext = 0
	do j=1,1
	kext = kext + qext(i,j)
	enddo
	do j=2,3
	kext = kext - qext(i,j)
	enddo
	print*,'Check zero-sum EP: ',i,kext
	enddo

c	stop
#endif

	end
